"""Report reviewed fixed passages; no GPU or inference."""
import json,re,hashlib
from pathlib import Path
B=Path(__file__).resolve().parent.parent;R=B/'experiments/prompt_pilot_v1/pilot-20261114-v1';O=R/'quality';a=json.loads((O/'paired_results.json').read_text());units=json.loads((B/'assistant_reference_v2/evaluation_units.json').read_text())
coverage=[]
for rec in a['records'][:3]:
 ls={l for p in rec['passages'] for l in p['reference_line_ids']};eligible=[u for u in units['units'] if u['page_id']==rec['page_id'] and u['strict_eligible']];chosen=[u for u in eligible if set(u['line_ids'])<=ls]
 coverage.append(dict(page=rec['sample'],frozen_profile_scored_tokens=sum(u['reference_token_count'] for u in chosen),frozen_profile_eligible_tokens=sum(u['reference_token_count'] for u in eligible),scored_units=len(chosen),eligible_units=len(eligible)))
a['coverage']=coverage
checks=[]
for rec in a['records']:
 assert hashlib.sha256(Path(rec['path']).read_bytes()).hexdigest()==rec['sha256']
 for p in rec['passages']:
  for key in ['word','character']:
   c=p[key];assert c['H']+c['S']+c['D']==c['N'];assert c['H']+c['S']+c['I']==c['M']
 for span in [s for p in rec['passages'] for s in p['raw_spans']]:assert 0<=span['start']<=span['end_exclusive']<=len(Path(rec['path']).read_text())
md=['# Evaluación pareada del piloto de instrucciones','','## Conclusión','','El prompt literal_regions_v1 no justifica sustituir el original para todos los documentos. En los pasajes claros revisados, Qwen3.5-9B conserva 22 errores de palabras; Qwen3.8-27B baja de 32 a 25. La mejora de 27B se concentra en el manuscrito, mientras introduce etiquetas de tachado incorrectas. Ambos aumentan el tiempo histórico de inferencia.','','## Alcance y método','','Se revisaron directamente las 12 transcripciones (2 modelos × 2 variantes × 3 páginas) contra Astra v2 fija. Las correspondencias usan fragmentos explícitos con offsets, agrupados por región/pasaje, sin penalizar reordenamientos del membrete. El JSON conserva hipótesis, referencia, conteos y todo texto fuera del alcance. Los errores de etiquetas se evalúan aparte del reconocimiento.','','Se puntúan 95 de 106 unidades estrictas del piloto: 679 de 719 tokens según el perfil congelado (94,44 %). Con el perfil común que equipara siglas espaciadas como D. D. y D.D., son 671 tokens y 3.904 caracteres. La diferencia de denominador proviene de normalización, no de descartar errores. Las mismas unidades se usan en las cuatro condiciones.','','Se excluyen 11 unidades claras contiguas a lecturas inciertas o de asignación más compleja, además del texto incierto, tachados y folios fuera del alcance seleccionado. Esas exclusiones figuran en los fragmentos no puntuados; no se afirma exactitud del 100 % de la página ni cobertura total de adiciones. La selección no es aleatoria ni un test independiente.','','WER usa Levenshtein sobre palabras normalizadas; CER usa Levenshtein independiente sobre cadenas físicas NFKC con espacios/saltos colapsados, conservando mayúsculas, puntuación y guiones. El CER refleja también diferencias en las palabras partidas; no se presenta como CER de una edición modernizada.','','## Resultado agregado','','| Modelo | Prompt | H | S | D | I | WER | CER textual |','|---|---|---:|---:|---:|---:|---:|---:|']
for row in a['summary']:
 w=row['word'];c=row['character'];md.append(f"| {row['model']} | {row['variant']} | {w['H']} | {w['S']} | {w['D']} | {w['I']} | {w['rate_percent']:.2f}% | {c['rate_percent']:.2f}% |")
md+=['','El WER de 27B baja 1,04 puntos porcentuales (7 errores menos; reducción relativa 21,9 %). En 9B el WER no cambia, aunque cambian errores concretos. Estos resultados no son directamente comparables con el WER global exploratorio anterior.','','## Por página','','| Modelo | Página | N | Errores anterior → nuevo | WER anterior → nuevo |','|---|---|---:|---:|---:|']
for model in ['qwen3.5-9b','qwen3.8-27b']:
 for sample in ['typed','handwritten','pdf_page_02']:
  old,new=[r for r in a['records'] if r['model']==model and r['sample']==sample];n=sum(p['word']['N'] for p in old['passages']);e1=sum(p['word']['errors'] for p in old['passages']);e2=sum(p['word']['errors'] for p in new['passages']);md.append(f'| {model} | {sample} | {n} | {e1} → {e2} | {100*e1/n:.2f}% → {100*e2/n:.2f}% |')
md+=['','## Lecturas y entidades revisadas','','- 27B recupera «ago you desired me to say anything I could / learn on the subject of national resources», frente a «ago your friend was to say a Thing I could / lean…». Aun así, «revenue» continúa mal leído: pasa de «new Coin» a «river Guns».','- 27B mantiene «artificial dikes» frente al «efficient levees» claro de Astra. En el miembro del directorio recupera Burrell, pero pierde Horton: no hay mejora neta de apellidos.','- 9B cambia «Fairfield» por «Harfield» en el saludo; ninguna coincide con Garfield. Cambia «efficient means» por «efficient laws»: sigue siendo incorrecto.','- En las 12 menciones de apellidos del directorio, el cotejo normalizado por apellido dentro del bloque da 8/12 para 9B antes y después, y 7/12 para 27B antes y después. Esta medida no acredita iniciales, nombres completos ni precisión de entidades predichas.','- Garfield se conserva correctamente en ambas salidas de 27B y falla en ambas de 9B. El año 1865 se conserva en las cuatro. No hay evidencia de mejora sobre los nombres y lugares prioritarios del Excel, que no están representados por este piloto.','','## Cumplimiento de instrucciones','','Las seis respuestas nuevas son parseables, pero eso no garantiza estructura documental correcta.','','- 9B no emite ninguna etiqueta DEL ni INS en las tres páginas. En PDF 2 omite la línea tachada del año; conserva «Case» sin marcar dentro de «Review Case, Record» y mantiene texto del pie tachado como si estuviera activo. Incumple la transcripción y etiquetado de las correcciones.','- 27B, PDF 2: marca «Present» como DEL aunque Astra lo registra como inserción. Marca Chief Judge Martial, Deputy Chief Judge Martial, Courts-Martial Appeal Court y Make up of Ct. como tachados, aunque Astra registra esas palabras como activas.','- 27B duplica «This composed / of 7 Men» en dos regiones marginales. La nota activa de Astra dice «This composed / of Officers»; la otra región corresponde a una nota tachada con lecturas inciertas, por lo que no se adjudica su contenido como «Men» correcto.','- 27B marca Civilian como inserción, mientras Astra lo registra en una región marginal activa. La separación de regiones mejora parcialmente, pero las etiquetas no pueden aplicarse automáticamente para filtrar el texto final.','- Ninguno usa UNCLEAR o ILLEGIBLE en estas respuestas pese a los errores observados. No se ha medido calibración de confianza.','','## Recursos y tiempo','','| Modelo | Histórico total (s) | Nuevo total (s) | Variación | Mínimo VRAM libre |','|---|---:|---:|---:|---:|']
resources=[json.loads(x) for x in (R/'resource_monitor.jsonl').read_text().splitlines()]
for model in ['qwen3.5-9b','qwen3.8-27b']:
 old=new=0
 for sample in ['typed','handwritten','pdf_page_02']:
  old+=json.loads((B/('extended_results' if sample.startswith('pdf') else 'results')/model/(sample+'.json')).read_text())['seconds'];new+=json.loads((R/'metadata/literal_regions_v1'/model/(sample+'.json')).read_text())['seconds']
 vr=min(x['vram_free_mib'] for x in resources if x['model']==model);md.append(f'| {model} | {old:.2f} | {new:.2f} | +{100*(new/old-1):.1f}% | {vr} MiB |')
md+=['','Son tiempos de inferencia, sin carga, y el control es histórico. No se estimó variabilidad entre repeticiones; temperatura cero no garantiza identidad bit a bit. Las seis salidas nuevas finalizaron con stop, sin truncamiento registrado ni errores del parser. No se cruzaron los mínimos de memoria monitorizados. El estado final de GPU registrado tras el piloto fue 15.828 MiB libres. En esta evaluación no se ejecutaron modelos.','','## Recomendación','','Mantener el prompt original como opción de uso general. Para 27B, conservar la variante nueva como experimental: mejora la lectura en un pasaje difícil, pero sus etiquetas de tachado son inseguras. Para 9B no hay ganancia neta de palabras que justifique el formato adicional. El siguiente ensayo útil es transcribir recortes de regiones con instrucciones literales breves, evaluando las mismas regiones y contabilizando el tiempo total; no aplicar automáticamente etiquetas DEL de estas salidas.','','Antes de procesar el archivo completo, confirmar con más páginas representativas de los apellidos y lugares buscados. No elegir el modelo por esta tabla de tres páginas.','','## Artefactos','','`paired_results.json` contiene asignaciones verificadas del subconjunto, offsets, lecturas, exclusiones y conteos; `validation.json` contiene verificaciones de integridad. Las asignaciones genéricas needs_review del piloto anterior no se sobrescriben: esta evaluación usa su propio subconjunto adjudicado.']
(O/'report.md').write_text('\n'.join(md)+'\n');(O/'paired_results.json').write_text(json.dumps(a,indent=2,ensure_ascii=False)+'\n')
(O/'validation.json').write_text(json.dumps(dict(valid=True,checks=['hypothesis hashes','same reference denominator across variants','Levenshtein invariants','reviewed span bounds','no selected-span overlap (assess_saved.py)','frozen reference manifest verified'],scored_units=95,eligible_units=106,reference_original_profile_tokens=679,eligible_original_profile_tokens=719,normalized_tokens=671,reference_characters=3904,limitations=['Scope excludes 11 eligible units and uncertain/deleted layers; not whole-page exhaustive recognition.','Manual boundary/region review by assistant against user-selected Astra, not human validation.','Historical control, single run, no statistical generalization.']),indent=2)+'\n')
print(str(O/'report.md'))
